-- Сброс последовательностей (чтобы следующие записи не конфликтовали)
SELECT setval(pg_get_serial_sequence('public."Пользователи"', 'Идентификатор_пользователя'), COALESCE((SELECT MAX("Идентификатор_пользователя") FROM public."Пользователи"), 1));
SELECT setval(pg_get_serial_sequence('public."Сотрудники"', 'Идентификатор_сотрудника'), COALESCE((SELECT MAX("Идентификатор_сотрудника") FROM public."Сотрудники"), 1));
SELECT setval(pg_get_serial_sequence('public."Инциденты"', 'Идентификатор_инцидента'), COALESCE((SELECT MAX("Идентификатор_инцидента") FROM public."Инциденты"), 1));
SELECT setval(pg_get_serial_sequence('public."Услуги"', 'Идентификатор_услуги'), COALESCE((SELECT MAX("Идентификатор_услуги") FROM public."Услуги"), 1));
SELECT setval(pg_get_serial_sequence('public."Уязвимости"', 'Идентификатор_уязвимости'), COALESCE((SELECT MAX("Идентификатор_уязвимости") FROM public."Уязвимости"), 1));
SELECT setval(pg_get_serial_sequence('public."Средства_защиты"', 'Идентификатор_средства'), COALESCE((SELECT MAX("Идентификатор_средства") FROM public."Средства_защиты"), 1));
SELECT setval(pg_get_serial_sequence('public."Меры_реагирования"', 'Идентификатор_меры'), COALESCE((SELECT MAX("Идентификатор_меры") FROM public."Меры_реагирования"), 1));
SELECT setval(pg_get_serial_sequence('public."Журнал_аудита"', 'Идентификатор_лога'), COALESCE((SELECT MAX("Идентификатор_лога") FROM public."Журнал_аудита"), 1));